import { z } from 'zod';

/** Every API ID is a UUID string generated by the API (UUIDv7, ADR-0012). */
export const idSchema = z.uuid({ error: 'Must be a valid ID.' });
export type Id = z.infer<typeof idSchema>;

/** CSRF: every state-changing request carries this header (SEC-003, ADR-0013). */
export const CSRF_HEADER_NAME = 'X-Requested-With';
export const CSRF_HEADER_VALUE = 'soloops';
export const REQUEST_ID_HEADER = 'X-Request-Id';
export const SESSION_COOKIE_NAME = 'soloops_sid';
/** Used when COOKIE_SECURE=true (production): the __Host- prefix forbids subdomain cookie injection. */
export const SECURE_SESSION_COOKIE_NAME = '__Host-soloops_sid';

/** Stable problem codes returned in problem+json `code` (docs/architecture/api-design.md §2–3). */
export const problemCodes = [
  'MALFORMED_JSON',
  'VALIDATION_FAILED',
  'UNAUTHENTICATED',
  'INVALID_CREDENTIALS',
  'REGISTRATION_FAILED',
  'FORBIDDEN',
  'CSRF_REJECTED',
  'NOT_FOUND',
  'PAYLOAD_TOO_LARGE',
  'RATE_LIMITED',
  'PRECONDITION_FAILED',
  'PRECONDITION_REQUIRED',
  'INVALID_STATE_TRANSITION',
  'VERSION_HASH_MISMATCH',
  'ALREADY_INVOICED',
  'AI_DISABLED',
  'ARCHIVED',
  /** BR-004 / AC-007.2: a baselined requirement is frozen; changes need a change request. */
  'BASELINE_LOCKED',
  'NOT_ELIGIBLE',
  'IDEMPOTENCY_KEY_REUSED',
  'SERVICE_UNAVAILABLE',
  /** AI provider failures (api-design §2: 502 / 504). The draft is never changed (AC-009.3). */
  'AI_TIMEOUT',
  'AI_PROVIDER_ERROR',
  'AI_INVALID_OUTPUT',
  'INTERNAL_ERROR',
] as const;
export const problemCodeSchema = z.enum(problemCodes);
export type ProblemCode = z.infer<typeof problemCodeSchema>;

export const fieldErrorSchema = z.object({ path: z.string(), message: z.string() });
export type FieldError = z.infer<typeof fieldErrorSchema>;

/** RFC 9457 problem details as returned by the API. */
export const problemSchema = z.object({
  type: z.string(),
  title: z.string(),
  status: z.number().int(),
  code: problemCodeSchema,
  detail: z.string().optional(),
  errors: z.array(fieldErrorSchema).optional(),
  requestId: z.string().optional(),
});
export type Problem = z.infer<typeof problemSchema>;

/**
 * Money crosses the API as a string of integer minor units (BR-019, api-design §1),
 * e.g. "150000" = ₹1,500.00. Bounded to the signed Int64 range used in MongoDB.
 */
const INT64_MAX = 9223372036854775807n;
export const minorUnitsSchema = z
  .string()
  // `abort` stops before the BigInt refinement, which would throw on a non-integer string.
  .regex(/^(0|[1-9]\d{0,18})$/, {
    error: 'Must be a non-negative whole number of minor units.',
    abort: true,
  })
  .refine((v) => BigInt(v) <= INT64_MAX, { error: 'Amount is too large.' });
export type MinorUnits = z.infer<typeof minorUnitsSchema>;

/** ISO 4217 alphabetic code. */
export const currencyCodeSchema = z
  .string()
  .regex(/^[A-Z]{3}$/, { error: 'Use a 3-letter ISO 4217 currency code, e.g. INR.' });

/** IANA time zone accepted by Intl (works in Node and browsers). */
export const timeZoneSchema = z
  .string()
  .min(1)
  .max(64)
  .refine(
    (tz) => {
      try {
        new Intl.DateTimeFormat('en', { timeZone: tz });
        return true;
      } catch {
        return false;
      }
    },
    { error: 'Use an IANA time zone such as Asia/Kolkata.' },
  );

/** Number of minor-unit digits for a currency (INR → 2, JPY → 0). Display/parse only. */
export function currencyFractionDigits(currency: string): number {
  return (
    new Intl.NumberFormat('en', { style: 'currency', currency }).resolvedOptions()
      .maximumFractionDigits ?? 2
  );
}

/**
 * Converts a user-typed decimal ("1,500.5") into a minor-unit string ("150050") without
 * floating point. Returns null if the input is not a valid non-negative amount for the
 * currency's precision. Used by inputs only; the API recomputes every total (BR-020).
 */
export function decimalToMinorUnits(input: string, fractionDigits: number): string | null {
  const cleaned = input.trim().replace(/,/g, '');
  const match = /^(\d+)(?:\.(\d*))?$/.exec(cleaned);
  if (!match) return null;
  const whole = match[1] ?? '0';
  const frac = match[2] ?? '';
  if (frac.length > fractionDigits) return null;
  const digits = (whole + frac.padEnd(fractionDigits, '0')).replace(/^0+(?=\d)/, '');
  return minorUnitsSchema.safeParse(digits).success ? digits : null;
}

/** Converts a minor-unit string to a plain decimal string ("150050", 2 → "1500.50"). */
export function minorUnitsToDecimal(minor: string, fractionDigits: number): string {
  if (fractionDigits === 0) return minor;
  const padded = minor.padStart(fractionDigits + 1, '0');
  return `${padded.slice(0, -fractionDigits)}.${padded.slice(-fractionDigits)}`;
}
